import React, { useState, useEffect, useCallback } from "react";
import {
  View,
  Text,
  StyleSheet,
  Image,
  FlatList,
  TouchableOpacity,
  ScrollView,
  Alert,
  Dimensions,
} from "react-native";
import { useNavigation, useFocusEffect } from "@react-navigation/native";
import initialState from "../../utils/user";
import lang from "../../utils/language";
import Loading from "../../components/Loading";
import { Button, Avatar, ListItem } from "react-native-elements";
import axios from "axios";
import Toast from "react-native-root-toast";

const windowWidth = Dimensions.get("window").width;
const windowHeight = Dimensions.get("window").height;

export default function UserLogged() {
  const navigation = useNavigation();
  const [language, setLanguage] = useState(lang.idioma);
  const [interesesUser, setInteresesUser] = useState(initialState.misIntereses);
  const [loading, setLoading] = useState(false);
  const [cargo, setCargo] = useState(initialState.cargo);
  const [actividad, setActividad] = useState(initialState.actividad);
  const [especie, setEspecie] = useState(initialState.especies);
  const [detalleEspecie, setDetalleEspecie] = useState(
    initialState.detallesEspecies
  );
  //const [update, setUpdate] = useState(false);

  //const listaIntereses = () => {
  //  for (let i = 0; i < initialState.misIntereses.length; i++) {
  //    const element = initialState.misIntereses[i];
  //  }
  //};

  const [cargos, setCargos] = useState([]);

  function ListCargos() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/cargo-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        console.log(response);
        setCargos(response);
      });
  }

  const [actividades, setActividades] = useState([]);

  function ListActividades() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/actividad-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        //console.log(response);
        setActividades(response);
      });
  }

  const [especies, setEspecies] = useState([]);
  //URL: la URL de tu endpoint API
  function listaEspecies() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/especies-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        console.log(response);
        setEspecies(response);
      });
  }

  const [detallesEspecies, setDetallesEspecies] = useState([]);
  //URL: la URL de tu endpoint API
  function listaDetallesEspecies() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/animals-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        console.log(response);
        setDetallesEspecies(response);
      });
  }

  useEffect(() => {
    setLoading(true);
    postIntereses();
    actualizaPerfil();
    ListCargos();
    ListActividades();
    listaEspecies();
    listaDetallesEspecies();
    setEspecie(initialState.especies);
    setCargo(initialState.cargo);
    setActividad(initialState.actividad);
    setDetalleEspecie(initialState.detallesEspecies);
  }, [language, interesesUser]);

  useFocusEffect(
    useCallback(() => {
      setLanguage(lang.idioma);
      setInteresesUser(initialState.misIntereses);
      //console.log(interesesUser);
    }, [lang, initialState])
  );

  const sendIntereses = (value) => {
    if (initialState.misIntereses.length > 5) {
      if (initialState.misIntereses.find((element) => element === `${value}`)) {
        for (var i = 0; i < initialState.misIntereses.length; i++) {
          if (initialState.misIntereses[i] === `${value}`) {
            initialState.misIntereses.splice(i, 1);
            axios
              .get(
                `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/intereses-app.php?id_user=${initialState.userID}&intereses=${initialState.misIntereses}`
              )
              .then(() => {
                setInteresesUser(initialState.misIntereses);
                console.log(interesesUser);
              })

              .then(function () {});
          }
        }
      }
    } else {
      Toast.show(
        language === "es"
          ? "No puedes tener menos de cinco intereses"
          : "Você não pode ter menos de cinco interesses",
        {
          position: Toast.positions.CENTER,
        }
      );
      console.log("menos de 5");
    }
  };

  function alertBorrarInteres(value, id) {
    return Alert.alert(
      language === "es"
        ? `¿Quiere eliminar el siguiente interés de su perfil? `
        : `Quer remover o seguinte interesse do seu perfil? `,
      `${value}`,
      //`${id}`,
      [
        {
          text: "Cancel",
          onPress: () => console.log("Cancel Pressed"),
          style: "cancel",
        },
        { text: "OK", onPress: () => sendIntereses(id) },
      ]
    );
  }

  function actualizaPerfil() {
    axios
      .get(
        `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/misintereses-app.php?id_user=${initialState.userID}}`
      )
      .then(function (response) {
        initialState.misIntereses = response.data[0].misintereses.split(",");
        initialState.cargo = response.data[0].cargo;
        initialState.actividad = response.data[0].actividad;
        initialState.especies = response.data[0].Especies.split(",");
        initialState.detallesEspecies =
          response.data[0].Detallesotros.split(",");
      })

      .then(function () {});
  }

  const [intereses, setIntereses] = useState();
  //URL: la URL de tu endpoint API
  function postIntereses() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-json/wp/v2/intereses/?per_page=100`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((responseJson) => {
        //alert(JSON.stringify(responseJson));
        //console.log(typeof responseJson);
        setIntereses(responseJson); //sale undefined quitar .results
        setLoading(false);

        //acf.link_podcast1
        //acf.imagen_podcast1
        //title.rendered Titulo del podcast
        //yoast_head_json.og_description Descripcion del podcast
      })
      .catch((error) => {
        //Error
        console.error(error);
      });
  }

  return (
    <ScrollView style={styles.container}>
      <Avatar
        size="small"
        source={
          language === "es"
            ? require("../../../assets/img/flag-spain.png")
            : require("../../../assets/img/flag-brazil.png")
        }
        rounded
        onPress={() => {
          navigation.push("select-language");
        }}
        activeOpacity={0.7}
        containerStyle={{
          alignSelf: "flex-end",
          marginTop: 35,
        }}
      />
      <Loading isVisible={loading} text="Cargando Podcast..." />
      {initialState.userImage !== "https://socialagri.com/imgperfil/" ? (
        <Image
          source={{ uri: initialState.userImage }}
          resizeMode="contain"
          style={styles.image}
        />
      ) : (
        <Image
          source={require("../../../assets/img/userDefault.png")}
          resizeMode="contain"
          style={styles.image}
        />
      )}
      <Text style={styles.title}>
        {language === "es" ? "Bienvenido" : "Bem vindo"} {initialState.username}{" "}
        {initialState.lastname}
      </Text>
      {cargos.length !== 0 &&
      actividades.length !== 0 &&
      especies.length !== 0 &&
      detallesEspecies.length !== 0 ? (
        <View
          style={{
            backgroundColor: "#594079",
            borderRadius: 10,
            paddingLeft: 15,
            paddingTop: 10,
            marginBottom: 30,
            paddingRight: 10,
          }}
        >
          <Text style={styles.titleh3}>
            {language === "es" ? "Móvil:" : "Celular:"} {initialState.movil}
          </Text>
          <Text style={styles.titleh3}>
            {language === "es" ? "Empresa:" : "Empresa:"} {initialState.empresa}
          </Text>
          <Text style={styles.titleh3}>
            {language === "es" ? "Cargo:" : "Cargo:"}{" "}
            {cargos
              ? cargo == cargos[0].id
                ? cargos[0].nombrees
                : cargo == cargos[1].id
                ? cargos[1].nombrees
                : cargo == cargos[2].id
                ? cargos[2].nombrees
                : cargo == cargos[3].id
                ? cargos[3].nombrees
                : cargo == cargos[4].id
                ? cargos[4].nombrees
                : cargo == cargos[5].id
                ? cargos[5].nombrees
                : cargo == cargos[6].id
                ? cargos[6].nombrees
                : cargo == cargos[7].id
                ? cargos[7].nombrees
                : cargo == cargos[8].id
                ? cargos[8].nombrees
                : cargo == cargos[9].id
                ? cargos[9].nombrees
                : cargos[10].nombrees
              : ""}
          </Text>
          <Text style={styles.titleh3}>
            {language === "es" ? "Actividad:" : "Atividade da Empresa:"}{" "}
            {actividades
              ? actividad == actividades[0].id
                ? actividades[0].nombrees
                : actividad == actividades[1].id
                ? actividades[1].nombrees
                : actividad == actividades[2].id
                ? actividades[2].nombrees
                : actividad == actividades[3].id
                ? actividades[3].nombrees
                : actividad == actividades[4].id
                ? actividades[4].nombrees
                : actividad == actividades[5].id
                ? actividades[5].nombrees
                : actividad == actividades[6].id
                ? actividades[6].nombrees
                : actividad == actividades[7].id
                ? actividades[7].nombrees
                : actividad == actividades[8].id
                ? actividades[8].nombrees
                : actividad == actividades[9].id
                ? actividades[9].nombrees
                : actividad == actividades[10].id
                ? actividades[10].nombrees
                : actividad == actividades[11].id
                ? actividades[11].nombrees
                : actividad == actividades[12].id
                ? actividades[12].nombrees
                : actividad == actividades[13].id
                ? actividades[13].nombrees
                : actividad == actividades[14].id
                ? actividades[14].nombrees
                : actividad == actividades[15].id
                ? actividades[15].nombrees
                : actividad == actividades[16].id
                ? actividades[16].nombrees
                : actividad == actividades[17].id
                ? actividades[17].nombrees
                : actividad == actividades[18].id
              : actividades[18].nombrees}
          </Text>
          <Text style={styles.titleh3}>
            {language === "es" ? "Especie:" : "Espécie:"}{" "}
            {especies && especie.length >= 1
              ? especie[0] == especies[0].id
                ? especies[0].nombrees
                : especie[0] == especies[1].id
                ? especies[1].nombrees
                : especie[0] == especies[2].id
                ? especies[2].nombrees
                : especie[0] == especies[3].id
                ? especies[3].nombrees
                : especie[0] == especies[4].id
                ? especies[4].nombrees
                : especie[0] == especies[5].id
                ? especies[5].nombrees
                : ""
              : ""}
            {especies && especie.length >= 2 ? ", " : ""}
            {especies && especie.length >= 2
              ? especie[1] == especies[0].id
                ? especies[0].nombrees
                : especie[1] == especies[1].id
                ? especies[1].nombrees
                : especie[1] == especies[2].id
                ? especies[2].nombrees
                : especie[1] == especies[3].id
                ? especies[3].nombrees
                : especie[1] == especies[4].id
                ? especies[4].nombrees
                : especie[0] == especies[5].id
                ? especies[5].nombrees
                : ""
              : ""}
            {especies && especie.length >= 3 ? ", " : ""}
            {especies && especie.length >= 3
              ? especie[2] == especies[0].id
                ? especies[0].nombrees
                : especie[2] == especies[1].id
                ? especies[1].nombrees
                : especie[2] == especies[2].id
                ? especies[2].nombrees
                : especie[2] == especies[3].id
                ? especies[3].nombrees
                : especie[2] == especies[4].id
                ? especies[4].nombrees
                : especie[2] == especies[5].id
                ? especies[5].nombrees
                : ""
              : ""}
            {especies && especie.length >= 4 ? ", " : ""}
            {especies && especie.length >= 4
              ? especie[3] == especies[0].id
                ? especies[0].nombrees
                : especie[3] == especies[1].id
                ? especies[1].nombrees
                : especie[3] == especies[2].id
                ? especies[2].nombrees
                : especie[3] == especies[3].id
                ? especies[3].nombrees
                : especie[3] == especies[4].id
                ? especies[4].nombrees
                : especie[3] == especies[5].id
                ? especies[5].nombrees
                : ""
              : ""}
            {especies && especie.length >= 5 ? ", " : ""}
            {especies && especie.length >= 5
              ? especie[4] == especies[0].id
                ? especies[0].nombrees
                : especie[4] == especies[1].id
                ? especies[1].nombrees
                : especie[4] == especies[2].id
                ? especies[2].nombrees
                : especie[4] == especies[3].id
                ? especies[3].nombrees
                : especie[4] == especies[4].id
                ? especies[4].nombrees
                : especie[4] == especies[5].id
                ? especies[5].nombrees
                : ""
              : ""}
            {especies && especie.length >= 6 ? ", " : ""}
            {especies && especie.length >= 6
              ? especie[5] == especies[0].id
                ? especies[0].nombrees
                : especie[5] == especies[1].id
                ? especies[1].nombrees
                : especie[5] == especies[2].id
                ? especies[2].nombrees
                : especie[5] == especies[3].id
                ? especies[3].nombrees
                : especie[5] == especies[4].id
                ? especies[4].nombrees
                : especie[5] == especies[5].id
                ? especies[5].nombrees
                : ""
              : ""}
          </Text>
          <Text style={styles.titleh3}>
            {language === "es"
              ? "Detalles de Especie:"
              : "Detalhes da Espécie:"}{" "}
            {detallesEspecies && detalleEspecie.length >= 1
              ? detalleEspecie[0] == detallesEspecies[0].id
                ? detallesEspecies[0].nombrees
                : detalleEspecie[0] == detallesEspecies[1].id
                ? detallesEspecies[1].nombrees
                : detalleEspecie[0] == detallesEspecies[2].id
                ? detallesEspecies[2].nombrees
                : detalleEspecie[0] == detallesEspecies[3].id
                ? detallesEspecies[3].nombrees
                : detalleEspecie[0] == detallesEspecies[4].id
                ? detallesEspecies[4].nombrees
                : detalleEspecie[0] == detallesEspecies[5].id
                ? detallesEspecies[5].nombrees
                : detalleEspecie[0] == detallesEspecies[6].id
                ? detallesEspecies[6].nombrees
                : detalleEspecie[0] == detallesEspecies[7].id
                ? detallesEspecies[7].nombrees
                : detalleEspecie[0] == detallesEspecies[8].id
                ? detallesEspecies[8].nombrees
                : detalleEspecie[0] == detallesEspecies[9].id
                ? detallesEspecies[9].nombrees
                : detalleEspecie[0] == detallesEspecies[10].id
                ? detallesEspecies[10].nombrees
                : detalleEspecie[0] == detallesEspecies[11].id
                ? detallesEspecies[11].nombrees
                : detalleEspecie[0] == detallesEspecies[12].id
                ? detallesEspecies[12].nombrees
                : detalleEspecie[0] == detallesEspecies[13].id
                ? detallesEspecies[13].nombrees
                : detalleEspecie[0] == detallesEspecies[14].id
                ? detallesEspecies[14].nombrees
                : detalleEspecie[0] == detallesEspecies[15].id
                ? detallesEspecies[15].nombrees
                : detalleEspecie[0] == detallesEspecies[16].id
                ? detallesEspecies[16].nombrees
                : detalleEspecie[0] == detallesEspecies[17].id
                ? detallesEspecies[17].nombrees
                : detalleEspecie[0] == detallesEspecies[18].id
                ? detallesEspecies[18].nombrees
                : detalleEspecie[0] == detallesEspecies[19].id
                ? detallesEspecies[19].nombrees
                : detalleEspecie[0] == detallesEspecies[20].id
                ? detallesEspecies[20].nombrees
                  ? detalleEspecie[0] == detallesEspecies[21].id
                  : detallesEspecies[21].nombrees
                : ""
              : ""}
            {detallesEspecies && detalleEspecie.length >= 2 ? ", " : ""}
            {detallesEspecies && detalleEspecie.length >= 2
              ? detalleEspecie[1] == detallesEspecies[0].id
                ? detallesEspecies[0].nombrees
                : detalleEspecie[1] == detallesEspecies[1].id
                ? detallesEspecies[1].nombrees
                : detalleEspecie[1] == detallesEspecies[2].id
                ? detallesEspecies[2].nombrees
                : detalleEspecie[1] == detallesEspecies[3].id
                ? detallesEspecies[3].nombrees
                : detalleEspecie[1] == detallesEspecies[4].id
                ? detallesEspecies[4].nombrees
                : detalleEspecie[1] == detallesEspecies[5].id
                ? detallesEspecies[5].nombrees
                : detalleEspecie[1] == detallesEspecies[6].id
                ? detallesEspecies[6].nombrees
                : detalleEspecie[1] == detallesEspecies[7].id
                ? detallesEspecies[7].nombrees
                : detalleEspecie[1] == detallesEspecies[8].id
                ? detallesEspecies[8].nombrees
                : detalleEspecie[1] == detallesEspecies[9].id
                ? detallesEspecies[9].nombrees
                : detalleEspecie[1] == detallesEspecies[10].id
                ? detallesEspecies[10].nombrees
                : detalleEspecie[1] == detallesEspecies[11].id
                ? detallesEspecies[11].nombrees
                : detalleEspecie[1] == detallesEspecies[12].id
                ? detallesEspecies[12].nombrees
                : detalleEspecie[1] == detallesEspecies[13].id
                ? detallesEspecies[13].nombrees
                : detalleEspecie[1] == detallesEspecies[14].id
                ? detallesEspecies[14].nombrees
                : detalleEspecie[1] == detallesEspecies[15].id
                ? detallesEspecies[15].nombrees
                : detalleEspecie[1] == detallesEspecies[16].id
                ? detallesEspecies[16].nombrees
                : detalleEspecie[1] == detallesEspecies[17].id
                ? detallesEspecies[17].nombrees
                : detalleEspecie[1] == detallesEspecies[18].id
                ? detallesEspecies[18].nombrees
                : detalleEspecie[1] == detallesEspecies[19].id
                ? detallesEspecies[19].nombrees
                : detalleEspecie[1] == detallesEspecies[20].id
                ? detallesEspecies[20].nombrees
                  ? detalleEspecie[1] == detallesEspecies[21].id
                  : detallesEspecies[21].nombrees
                : ""
              : ""}
            {detallesEspecies && detalleEspecie.length >= 3 ? ", " : ""}
            {detallesEspecies && detalleEspecie.length >= 3
              ? detalleEspecie[2] == detallesEspecies[0].id
                ? detallesEspecies[0].nombrees
                : detalleEspecie[2] == detallesEspecies[1].id
                ? detallesEspecies[1].nombrees
                : detalleEspecie[2] == detallesEspecies[2].id
                ? detallesEspecies[2].nombrees
                : detalleEspecie[2] == detallesEspecies[3].id
                ? detallesEspecies[3].nombrees
                : detalleEspecie[2] == detallesEspecies[4].id
                ? detallesEspecies[4].nombrees
                : detalleEspecie[2] == detallesEspecies[5].id
                ? detallesEspecies[5].nombrees
                : detalleEspecie[2] == detallesEspecies[6].id
                ? detallesEspecies[6].nombrees
                : detalleEspecie[2] == detallesEspecies[7].id
                ? detallesEspecies[7].nombrees
                : detalleEspecie[2] == detallesEspecies[8].id
                ? detallesEspecies[8].nombrees
                : detalleEspecie[2] == detallesEspecies[9].id
                ? detallesEspecies[9].nombrees
                : detalleEspecie[2] == detallesEspecies[10].id
                ? detallesEspecies[10].nombrees
                : detalleEspecie[2] == detallesEspecies[11].id
                ? detallesEspecies[11].nombrees
                : detalleEspecie[2] == detallesEspecies[12].id
                ? detallesEspecies[12].nombrees
                : detalleEspecie[2] == detallesEspecies[13].id
                ? detallesEspecies[13].nombrees
                : detalleEspecie[2] == detallesEspecies[14].id
                ? detallesEspecies[14].nombrees
                : detalleEspecie[2] == detallesEspecies[15].id
                ? detallesEspecies[15].nombrees
                : detalleEspecie[2] == detallesEspecies[16].id
                ? detallesEspecies[16].nombrees
                : detalleEspecie[2] == detallesEspecies[17].id
                ? detallesEspecies[17].nombrees
                : detalleEspecie[2] == detallesEspecies[18].id
                ? detallesEspecies[18].nombrees
                : detalleEspecie[2] == detallesEspecies[19].id
                ? detallesEspecies[19].nombrees
                : detalleEspecie[2] == detallesEspecies[20].id
                ? detallesEspecies[20].nombrees
                  ? detalleEspecie[2] == detallesEspecies[21].id
                  : detallesEspecies[21].nombrees
                : ""
              : ""}
            {detallesEspecies && detalleEspecie.length >= 4 ? ", " : ""}
            {detallesEspecies && detalleEspecie.length >= 4
              ? detalleEspecie[3] == detallesEspecies[0].id
                ? detallesEspecies[0].nombrees
